css:
.stcbl-print {
    font-family: Arial, Helvetica, sans-serif;
    font-size: 12pt;
    color: #000;
    width: 100%;
    line-height: 1.25;
}

.hidden-pdf {
    margin-bottom: 6px;
}

.letter-head {
    width: 100%;
}

.top-strip {
    width: 100%;
    display: table;
    table-layout: fixed;
    margin-bottom: 4px;
    font-size: 12pt;
}

.bank-info,
.title-center,
.copy-text {
    display: table-cell;
    vertical-align: middle;
}

.bank-info {
    width: 35%;
    text-align: left;
}

.title-center {
    width: 30%;
    text-align: center;
    font-size: 13px;
}

.copy-text {
    width: 35%;
    text-align: right;
}

.main-info-table,
.item-table,
.totals-table,
.sign-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
}

.main-info-table td,
.item-table th,
.item-table td,
.totals-table td,
.sign-table td {
    border: 1px solid #000;
    padding: 6px 8px;
    vertical-align: top;
 
}
.item-table thead th {
    text-align: center;
    font-weight: bold;
    font-size: 8.5px;
    line-height: 1.1;
    vertical-align: middle;
    padding: 3px 3px;
    white-space: normal;
}

.left-box {
    width: 50%;
    min-height: 90px;
}

.right-box {
    width: 50%;
    padding: 0 !important;
}

.shipto-box {
    min-height: 80px;
}

.empty-box {
    background: #fff;
}

.section-label {
    margin-bottom: 6px;
    font-size: 11px;
}

.value-line {
    margin-bottom: 3px;
}

.value-line.strong {
    font-weight: bold;
}

.value-line.small {
    font-size: 10px;
}

.info-grid {
    width: 100%;
    border-collapse: collapse !important;
    table-layout: fixed;
}

.info-grid td {
    border: none;
    padding: 6px 10px;
    vertical-align: top;
    font-size: 10.5px;
}

.info-grid tr:last-child td {
    border-bottom: none;
}

.info-grid .label {
    width: 48%;
    font-weight: bold;
    text-align: left;
    vertical-align: top;
    padding: 4px 6px;
}

.info-grid .value {
    width: 52%;
    text-align: left;
    vertical-align: top;
    padding: 4px 6px;
}
.item-table {
    margin-top: -1px;
}

/*.section-divider td {*/
/*    border-top: 1px solid #000 !important;*/
/*    padding: 0 !important;*/
/*    height: 4px;*/
/*}*/

.full-divider td {
    padding: 0 !important;
    height: 6px !important;
    line-height: 0 !important;
    border-top: 1px solid #000 !important;
}

.item-table tbody td {
    font-size: 10px;
}

.item-table tbody td {
    font-size: 10px;
}

.w-sr { width: 5%; }
.w-no { width: 10%; }
.w-model { width: 12%; }
.w-btc { width: 9%; }
.w-desc { width: 26%; }
.w-qty { width: 5%; }
.w-uom { width: 7%; }
.w-rate { width: 13%; }
.w-amt { width: 13%; }

.text-center {
    text-align: center;
    vertical-align: middle !important;
}

.text-right {
    text-align: right;
    vertical-align: middle !important;
}

.desc-cell {
    min-height: 160px;
    line-height: 1.35;
}

.extra-line {
    margin-top: 6px;
}

.empty-row td {
    height: 24px;
}

.totals-table {
    margin-top: -1px;
}

.left-total-blank {
    width: 63%;
    height: 95px;
}

.right-total-box {
    width: 37%;
    padding: 0 !important;
}

.totals-inner {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
}

.totals-inner td {
    border: none;
    padding: 2px 6px;
    font-size: 10.5px;
}

.totals-inner .label {
    text-align: right;
    width: 68%;
}

.totals-inner .value {
    text-align: right;
    width: 32%;
}

.grand-total-row td {
    border-top: 1px solid #000;
    padding-top: 4px;
}

.amount-words-box {
    border: 1px solid #000;
    border-top: none;
    padding: 6px 8px;
    margin-top: -1px;
}

.amount-label {
    margin-bottom: 4px;
    font-size: 11px;
}

.amount-value {
    font-size: 11px;
    text-transform: uppercase;
}

.sign-table {
    margin-top: 20px;
}

.sign-table td {
    height: 55px;
    vertical-align: bottom;
    text-align: center;
    font-weight: bold;
}

.sign-left,
.sign-right {
    width: 50%;
}
.label-col {
    width: 60%;
    font-weight: bold;
    text-align: left;
    white-space: nowrap;
    padding: 6px 10px;
}

.value-col {
    width: 40%;
    text-align: left;
    padding: 6px 10px;
}
.full-line td,
.full-line-cell {
    padding: 0 !important;
    margin: 0 !important;
    height: 0 !important;
    line-height: 0 !important;
    border: none !important;
    border-top: 1px solid #000 !important;
}

.no-pad-grid {
    width: 100%;
    border-collapse: collapse !important;
    table-layout: fixed;
}

.no-pad-grid td {
    border: none !important;
    padding: 6px 10px;
    vertical-align: top;
    font-size: 10.5px;
}

.no-pad-grid .label-col {
    width: 60%;
    font-weight: bold;
    text-align: left;
    white-space: nowrap;
}

.no-pad-grid .value-col {
    width: 40%;
    text-align: left;
}

.no-pad-grid .divider-holder {
    padding: 0 !important;
    height: 0 !important;
    line-height: 0 !important;
}

.no-pad-grid .edge-divider {
    width: calc(100% + 20px);
    margin-left: -10px;
    border-top: 1px solid #000;
    
}

/* ===== Bottom section like real document ===== */

/* ===== Corrected lower section like real invoice ===== */

/* ===== Bottom section like real document ===== */
/* ===== Bottom section like real invoice ===== */

.bottom-summary-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    margin-top: -1px;
}

.bottom-summary-table td {
    border: 1px solid #000;
    padding: 0;
    vertical-align: top;
}

.bottom-left-blank {
    width: 62%;
    height: 170px;
    font-size: 12pt;
}

.bottom-right-summary {
    width: 39%;
}

.summary-inner-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    height: 100%;
}

.summary-inner-table td {
    border: none;
    padding: 4px 8px;
    font-size: 10px;
    line-height: 1.2;
    vertical-align: middle;
}

.sum-label {
    width: 68%;
    text-align: right;
    white-space: nowrap;
    font-weight: 600;
}

.sum-value {
    width: 32%;
    text-align: right;
    white-space: nowrap;
    border-left: 1px solid #000;
    padding-left: 8px
}

.summary-total-row td {
    border-top: none !important;
}

.total-label,
.total-value {
    font-weight: 700;
}

.amount-ngultrum-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    margin-top: -1px;
}

.amount-ngultrum-table td {
    border: 1px solid #000;
    padding: 4px 8px 6px 8px;
    vertical-align: top;
}

.amount-ngultrum-label {
    font-size: 11px;
    font-weight: 700;
    margin-bottom: 3px;
}

.amount-ngultrum-value {
    font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
    line-height: 1.25;
}

.header-with-qr {
    position: relative;
    width: 100%;
    padding-right: 110px;  /* reserve space for QR */
}

/* QR container */
.qr-container {
    position: absolute;
    top: 5px;
    right: 0;   /* align properly to edge */
}

/* QR image */
.qr-image {
    width: 90px;
    height: auto;
}
@media print {
    .stcbl-print {
        font-size: 10.5px;
    }

    .item-table thead {
        display: table-header-group;
    }

    tr, td, th {
        page-break-inside: avoid;
    }
}
